"""Versioned analytic probes; never generated by a candidate pitch shifter."""
import math
from pathlib import Path

from evaluation_common import (encode_pcm24, load_json, midi_hz, pcm_sha256, require, sha256,
                               validate_controls, write_json, write_wav)

GENERATOR = "voxide.analytic-fixtures.v2"
SEED = 0x564F5849
CASES = ("sine-low", "sine-mid", "sine-high", "output-low", "output-high", "missing-fundamental", "pitch-step",
         "glide", "vibrato", "vowel-resonances", "noise-bursts", "silence", "level-step", "bleed")


def noise(count, seed=SEED):
    state = seed
    result = []
    for _ in range(count):
        state = (1664525 * state + 1013904223) & 0xffffffff
        result.append(state / 2147483648.0 - 1.0)
    return result


def resonator_probe(rate, count, resonances=(650, 1100, 2450)):
    excitation = noise(count)
    output = [0.0] * count
    for frequency, bandwidth in zip(resonances, (55, 75, 100)):
        radius = math.exp(-math.pi * bandwidth / rate)
        coefficient = 2 * radius * math.cos(2 * math.pi * frequency / rate)
        previous, older = 0.0, 0.0
        band = []
        for value in excitation:
            current = value + coefficient * previous - radius * radius * older
            band.append(current)
            older, previous = previous, current
        rms = math.sqrt(sum(x * x for x in band) / count)
        for i, value in enumerate(band):
            output[i] += value / rms
    peak = max(abs(x) for x in output)
    return [x * 0.25 / peak for x in output]


def synthesize(case, rate):
    require(case in CASES and rate in (44100, 48000), "Unknown fixture configuration")
    count = rate if case == "vowel-resonances" else rate // 4
    random = noise(count)
    phase = 0.0
    samples, truth = [], []
    for i in range(count):
        time = i / rate
        f0 = {"sine-low": midi_hz(40), "sine-high": midi_hz(84),
              "output-low": midi_hz(16), "output-high": midi_hz(108)}.get(case, 220.0)
        if case == "pitch-step":
            f0 = midi_hz(55 if i < count // 2 else 59)
        elif case == "glide":
            f0 = 220 * 2 ** (i / (count - 1))
        elif case == "vibrato":
            f0 = 220 * 2 ** (50 * math.sin(2 * math.pi * 5 * time) / 1200)
        phase += 2 * math.pi * f0 / rate
        value = 0.125 * math.sin(phase)
        if case == "missing-fundamental":
            value = sum(0.06 * math.sin(harmonic * phase) for harmonic in (2, 3, 4))
        elif case == "bleed":
            value += 0.04 * math.sin(2 * math.pi * 317 * time) + 0.005 * random[i]
        elif case == "level-step":
            value *= 0.1 if i < count // 2 else 1
        elif case == "noise-bursts":
            value = 0.1 * random[i] if count // 3 <= i < 2 * count // 3 else 0.0
        elif case == "silence":
            value = 0.0
        samples.append(value)
        if i % (rate // 100) == 0:
            unvoiced = case in ("noise-bursts", "silence", "vowel-resonances")
            boundary = case in ("pitch-step", "level-step") and abs(i - count // 2) < rate * 0.05
            stable = not boundary and case not in ("glide", "vibrato", "bleed")
            truth.append({"sample": i, "voiced": not unvoiced, "f0_hz": None if unvoiced else f0,
                          "stable": stable, "uncertain": case == "bleed"})
    if case == "vowel-resonances":
        samples = resonator_probe(rate, count)
    source_pcm = pcm_sha256({"sample_rate": rate, "channels": 1, "bits": 24, "frames": count}, encode_pcm24(samples))
    controls = {"schema": "voxide.controls.v2", "source_id": case + "-" + str(rate),
                "source_pcm_sha256": source_pcm, "sample_rate": rate, "frames": count, "events": []}
    # Include event ordering at one timestamp and pitches covering full MIDI range.
    for index, (sample, kind, note, velocity) in enumerate(
            ((7, "note_on", 0, 80), (23, "note_off", 0, 0),
             (count // 2, "note_on", 60, 80), (count // 2, "note_off", 60, 0),
             (count - 2, "note_on", 127, 80), (count - 1, "note_off", 127, 0))):
        controls["events"].append({"id": "event-" + str(index), "sample": sample,
                                   "kind": kind, "channel": 1, "note": note, "velocity": velocity})
    landmarks = [] if case == "silence" else [{"id": "onset", "kind": "onset",
        "sample": count // 3 if case == "noise-bursts" else 0, "uncertainty_samples": 0}]
    if case == "pitch-step":
        landmarks.append({"id": "transition", "kind": "transition", "sample": count // 2, "uncertainty_samples": 0})
    reference = {"schema": "voxide.annotation.v2", "source_id": case + "-" + str(rate),
                 "source_pcm_sha256": source_pcm,
                 "annotator_id": "analytic-oracle-v1", "origin": "synthetic", "sample_rate": rate,
                 "frames": count, "grid": truth, "landmarks": landmarks,
                 "resonances_hz": [650, 1100, 2450] if case == "vowel-resonances" else [],
                 "static_shift_ratios": [{"semitones": shift, "ratio": 2 ** (shift / 12)}
                                         for shift in (-24, -12, -7, -3, 0, 3, 7, 12, 24)],
                 "scope": "Analytic control truth, not a human vocal annotation or shifter output"}
    return samples, reference, controls


def generate(directory):
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=False)
    catalog = {"schema": "voxide.fixtures.v1", "generator": GENERATOR, "seed": SEED,
               "pcm": "mono PCM24", "cases": []}
    for rate in (44100, 48000):
        for case in CASES:
            samples, reference, controls = synthesize(case, rate)
            stem = case + "-" + str(rate)
            paths = {"audio": directory / (stem + ".wav"), "reference": directory / (stem + ".json"),
                     "controls": directory / (stem + "-controls.json")}
            write_wav(paths["audio"], rate, samples)
            write_json(paths["reference"], reference)
            write_json(paths["controls"], controls)
            catalog["cases"].append({"id": stem, "case": case, "sample_rate": rate, "frames": len(samples),
                                      "files": {kind: {"path": path.name, "sha256": sha256(path)}
                                                for kind, path in paths.items()}})
    write_json(directory / "catalog.json", catalog)
    return catalog


def validate(directory):
    from evaluation_corpus import validate_annotation
    from evaluation_common import contained, wav_identity
    directory = Path(directory)
    catalog = load_json(directory / "catalog.json")
    require(catalog.get("schema") == "voxide.fixtures.v1" and catalog.get("generator") == GENERATOR
            and catalog.get("seed") == SEED,
            "Unsupported fixture catalog")
    expected = {case + "-" + str(rate) for rate in (44100, 48000) for case in CASES}
    ids = [entry["id"] for entry in catalog["cases"]]
    require(len(ids) == len(expected) and set(ids) == expected, "Missing/duplicate fixture cases")
    for entry in catalog["cases"]:
        require(entry["id"] == entry["case"] + "-" + str(entry["sample_rate"]), "Fixture identity mismatch")
        require(set(entry["files"]) == {"audio", "reference", "controls"}, "Missing fixture role")
        paths = {}
        for role, record in entry["files"].items():
            path = contained(directory, record["path"])
            require(sha256(path) == record["sha256"], "Fixture checksum mismatch: " + entry["id"])
            paths[role] = path
        info, audio_pcm = wav_identity(paths["audio"])
        require(info["sample_rate"] == entry["sample_rate"] and info["frames"] == entry["frames"],
                "Fixture WAV metadata mismatch")
        validate_annotation(load_json(paths["reference"]), entry["id"], info, audio_pcm)
        controls = load_json(paths["controls"])
        require(controls.get("source_id") == entry["id"], "Fixture control identity mismatch")
        validate_controls(controls, info, audio_pcm)
    return catalog
